cat > main.go <<'EOF'
package main

import (
	"fmt"

	"github.com/stretchr/objx"
)

func main() {
	m := objx.MustFromJSON(`{"user":{"name":"Ada","tags":["admin","dev"]}}`)

	// Read nested values with dot/array notation and typed accessors.
	fmt.Println(m.Get("user.name").Str())
	fmt.Println(m.Get("user.tags[0]").Str())
	fmt.Println(m.Get("user.age").Int(42)) // default when missing

	// Chainable mutation.
	m.Set("user.email", "ada@example.com").Set("active", true)
	fmt.Println(m.MustJSON())
}
EOF
cat > main_test.go <<'EOF'
package main

import (
	"testing"

	"github.com/stretchr/objx"
)

func TestObjxAccess(t *testing.T) {
	m := objx.Map{"a": map[string]interface{}{"b": []interface{}{"x", "y"}}}

	if got := m.Get("a.b[1]").Str(); got != "y" {
		t.Fatalf("a.b[1] = %q, want %q", got, "y")
	}

	m.Set("a.c", 7).Set("d", "z")
	if got := m.Get("a.c").Int(); got != 7 {
		t.Fatalf("a.c = %d, want 7", got)
	}
	if !m.Has("d") {
		t.Fatal("expected key d to exist")
	}
}
EOF
